/* Shared, source-verified APP 3.9.1 skill data; browser rendering only. */
(()=>{'use strict';
const D=window.SKILLS92_DATA,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prefix={inspiration:'诗人',valor:'战士',light:'牧师',shadow:'游荡者',arcana:'法师',wandering:'游侠'};
const equipment={inspiration:['鲁特琴','短刀','刺针弩'],valor:['剑','盾牌','长矛'],light:['法杖','医药包','聚辉器'],shadow:['匕首','陷阱','苦无'],arcana:['叉杖','细剑','魔典'],wandering:['弓','箭袋','猎刀']};
const colours={'#406729':'green','#ae9229':'gold','#24627a':'blue','#a45d2b':'orange','#752a67':'purple','#892e45':'red'};
const shades=['#f5f6f2','#d5d8d4','#adb3af'],tiers=['#ffffff','#bcbdc0','#58595b'];
let H,view=null;const image=k=>D.material[k],tile=(p,id)=>D.tiles[p][id];
const tokenIcon=k=>D.icons[k==='marker_white'?'marker':k==='journal'?'rp':k==='shield'?'defense':k==='first_damage'?'bonus_damage':k];
const notePath='M0 0 L-1.303 1.785 L-1.621 1.489 L-1.621 .652 L-.776 -2.773 C-1.099 -2.522 -1.537 -2.366 -2.023 -2.366 C-3.014 -2.366 -3.817 -3.008 -3.817 -3.8 C-3.817 -4.593 -3.014 -5.235 -2.023 -5.235 C-1.034 -5.235 -.23 -4.593 -.23 -3.8 L-1.077 .652 L.283 -1.303 Z';
function note(){return '<svg class="s92-note" viewBox="-4 -2 5 8" role="img" aria-label="乐曲结果"><g transform="translate(0 -3.45) scale(1 -1)"><path fill="currentColor" d="'+notePath+'"/></g></svg>';}
function symbol(k){if(k==='song')return note();if(k.startsWith('refresh_'))return refresh(k.slice(8));const src=tokenIcon(k);return src?`<img class="s92-icon" src="${E(src)}" alt="${E(D.names[k]||k)}">`:`<span class="s92-term">${E(D.names[k]||k)}</span>`;}
function text(s){return E(s).replace(/\{([a-z_0-9]+)\}/g,(_,k)=>symbol(k)).replace(/\n/g,'<br>');}
const img=(k,cls='',alt='')=>`<img class="${cls}" src="${image(k)}" alt="${E(alt)}">`;
function pathData(commands){return commands.map(([c,...pts])=>c.toUpperCase()+pts.flat().join(' ')).join(' ');}
function refresh(key){const a=D.refresh[key]||D.refresh.none;return `<svg class="s92-icon" viewBox="0 0 ${a.width} ${a.height}" role="img" aria-label="刷新标记">${a.parts.map(p=>`<path d="${pathData(p.commands)}" fill="${p.fill||'none'}" fill-rule="${p.evenOdd?'evenodd':'nonzero'}" stroke="${p.stroke||'none'}" stroke-width="${p.width||0}" ${p.dash?`stroke-dasharray="${p.dash[0].join(' ')}"`:''}/>`).join('')}</svg>`;}
function categories(p,id){return D.layout[p].nodes.find(n=>n.id===+id).background.match(/#[\da-f]{6}/gi).map(c=>colours[c.toLowerCase()]||'blue');}
function paints(p,id){const cs=categories(p,id);return cs.map((c,i)=>`<span class="s92-tree-paint" style="clip-path:inset(0 ${(1-(i+1)/cs.length)*100}% 0 ${i/cs.length*100}%);--tree-art:url('${image('art50_card_'+c)}')"><i></i><i></i></span>`).join('');}
function node(c,p,sk){const st=c.skills[sk.id]||{},locked=tile(p.id,sk.id).requires.some(id=>!c.skills[id]?.learned);return `<section class="replica-skill s92-node" data-node="${sk.id}" data-learned="${!!st.learned}">${paints(p.id,sk.id)}<button class="s92-tree-title" data-action="skillInfo" data-skill="${sk.id}" aria-label="${E(sk.name)} · 技能详情">${E(sk.name)}</button><div class="s92-tree-strip"><span class="s92-tree-code" style="background-image:url('${image('art50_badge_'+p.id)}')">${E(p.prefix)}-${sk.id}</span><div class="s92-checks">${[['learned','习得','learn'],['mastered','掌握','mastery']].map(([k,label,art])=>`<button class="tree-square s92-tree-check ${st[k]?'on':''} ${locked&&!st[k]?'is-locked':''}" role="checkbox" aria-checked="${!!st[k]}" aria-label="${E(sk.name)} ${label}" data-action="skillCheck" data-skill="${sk.id}" data-key="${k}">${img('art50_'+art,'s92-status-mark',label)}<span class="s92-check-art">${img('art50_checkbox')}${st[k]?img('art50_checked','s92-tick'):''}</span></button>`).join('')}</div></div></section>`;}
function legend(){return `<span class="s92-tree-legend">${img('art50_learn','','习得')}习得 ${img('art50_mastery','','掌握')}掌握</span>`;}
function music(g){const u=20,x=3,y=3,outline='M3 3H63V23H83V43H63V63H3Z';return `<svg class="s92-music" viewBox="0 0 86 66" role="img" aria-label="乐曲图：${g.notes.map(([c,r])=>`第${r+1}行第${c+1}列有音符`).join('；')}"><path d="${outline}" fill="#dcdddf" stroke="#231f20" stroke-width=".85"/><path d="M23 3V63M43 3V63M63 3V63M3 23H83M3 43H83" fill="none" stroke="#231f20" stroke-width=".85"/><path d="M1.6 1.6H64.4M1.6 64.4H64.4" stroke="#2498cf" stroke-width="1.7"/><path d="M1.6 1.6V64.4" stroke="#cf3d33" stroke-width="1.7"/><path d="M64.4 1.6V21.6H84.4V44.4H64.4V64.4" fill="none" stroke="#e8cf25" stroke-width="1.7"/>${g.notes.map(([c,r])=>`<g transform="translate(${x+c*u+.48*u+2.023*u/6.499} ${y+r*u+.48*u-3.8*u/6.499}) scale(${u/6.499} ${-u/6.499})"><path d="${notePath}" fill="#231f20"/></g>`).join('')}</svg>`;}
function arrow(ax,ay,bx,by,color='#939598',head=8,half=5,shaft=1.3){const dx=bx-ax,dy=by-ay,len=Math.hypot(dx,dy);if(!len)return '';const ux=dx/len,uy=dy/len,h=Math.min(head,len*.8),qx=bx-ux*h,qy=by-uy*h;return `<path d="M${bx} ${by}L${qx-uy*half} ${qy+ux*half}L${qx-uy*shaft} ${qy+ux*shaft}L${ax-uy*shaft} ${ay+ux*shaft}L${ax+uy*shaft} ${ay-ux*shaft}L${qx+uy*shaft} ${qy-ux*shaft}L${qx+uy*half} ${qy-ux*half}Z" fill="${color}"/>`;}
function grid(d){const rows=d.cells,cols=Math.max(...rows.map(r=>r.length)),u=27,extra=d.externalCross?.8:0,x=extra*u+2,y=2;let out='',origin=[Math.floor(cols/2),Math.floor(rows.length/2)];rows.forEach((r,j)=>[...r].forEach((ch,i)=>{if(ch==='@')origin=[i,j];if(ch===' ')return;out+=`<rect x="${x+i*u+1.5}" y="${y+j*u+1.5}" width="24" height="24" fill="${ch==='3'?'#919498':'#dcdddf'}" stroke="${ch==='R'?'#be3c3e':ch==='T'?'#231f20':'#939598'}" stroke-width="${'TR'.includes(ch)?1.3:.55}" ${ch==='T'&&d.dashed?'stroke-dasharray="3 2"':''}/>`;}));const cx=x+(origin[0]+.5)*u,cy=y+(origin[1]+.5)*u;
if(d.push){let targets=[];rows.forEach((r,j)=>[...r].forEach((ch,i)=>{if(ch==='X'){targets.push(j);const px=x+(i+.5)*u,py=y+(j+.5)*u;out+=arrow(px,py,px-u,py)+arrow(px,py,px+u,py);}}));if(targets.length)out+=arrow(cx,cy-u*.36,cx,y+(Math.min(...targets)+.65)*u,'#935658',u*.48,u*.30);}
if(d.diagonal)for(const dx of [-1,1])for(const dy of [-1,1])out+=arrow(cx,cy,cx+dx*u,cy+dy*u);
if(d.rays)for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)if(dx||dy)out+=arrow(cx,cy,cx+dx*u*1.4,cy+dy*u*1.4);
if(d.extend)out+=arrow(cx,cy,cx,y+u*.12);
rows.forEach((r,j)=>[...r].forEach((ch,i)=>{const px=x+(i+.5)*u,py=y+(j+.5)*u;if(ch==='@'){const kind=d.origin||'melee';if(kind==='target'){out+=d.centerHit?`<image href="${tokenIcon('grid_enemy')}" x="${px-9}" y="${py-9}" width="18" height="18"/>`:`<circle cx="${px}" cy="${py}" r="2.7" fill="#231f20"/>`;}else{out+=`<circle cx="${px}" cy="${py}" r="10.8" fill="#b2b2b2"/><image href="${tokenIcon(kind==='melee'?'grid_melee':kind)}" x="${px-9}" y="${py-9}" width="18" height="18"/>`;}}else if('XTR'.includes(ch)&&!d.diagonal)out+=d.target==='distance'?`<circle cx="${px}" cy="${py}" r="6" fill="none" stroke="#231f20" stroke-width="1.5"/>`:`<image href="${tokenIcon('grid_enemy')}" x="${px-9}" y="${py-9}" width="18" height="18"/>`;else if('23'.includes(ch))out+=`<text x="${px}" y="${py+6}" text-anchor="middle" font-size="18" fill="#231f20">${ch}</text>`;}));
if(d.corner)out+=d.cornerSymbol?`<image href="${tokenIcon(d.cornerSymbol)}" x="${x+u-6}" y="${y+u-6}" width="12" height="12"/>`:`<circle cx="${x+u}" cy="${y+u}" r="2.7" fill="#bc993e"/>`;
if(d.externalCross)out+=`<image href="${tokenIcon('grid_red_cross')}" x="${x-u*.83}" y="${y+rows.length*u/2-u*.48}" width="${u*.96}" height="${u*.96}"/>`;
return `<svg class="s92-grid" viewBox="0 0 ${(cols+extra)*u+4} ${rows.length*u+4}" role="img" aria-label="${E(d.title||'位置图')}：${E(rows.join('；'))}">${out}</svg>`;}
function track(d){const nodes=d.nodes,r=8,s=d.spacingDp||20,xy=nodes.map(n=>[n.x*s,n.y*s]),tails=nodes.map(()=>({})),contour=[[0,-1],[.28,-.71],[.7,-.71],[.7,-.29],[1,0],[.7,.29],[.7,.71],[.28,.71],[0,1],[-.28,.71],[-.7,.71],[-.7,.29],[-1,0],[-.7,-.29],[-.7,-.71],[-.28,-.71]];let arrows='';
function extend(i,dx,dy,len){const z=Math.hypot(dx,dy)||1,ux=dx/z,uy=dy/z;let best=0,score=-Infinity;for(let k=0;k<16;k+=2){const q=contour[k],v=(q[0]*ux+q[1]*uy)/Math.hypot(...q);if(v>score){score=v;best=k;}}tails[i][best]=[ux*len,uy*len];}
for(const [a,b]of d.edges){const dx=xy[a][0]-xy[b][0],dy=xy[a][1]-xy[b][1];extend(b,dx,dy,Math.max(r,Math.hypot(dx,dy)-r*.75));}
if(d.entry!=='cross')for(const [i,v] of (d.starts||[d.start||[0,1]]).entries()){const [dx,dy]=v,z=Math.hypot(dx,dy)||1,ux=dx/z,uy=dy/z,[x,y]=xy[i],single=!d.edges.some(e=>e.includes(i)),near=r*(single?1.5:1.37),far=r*(single?2.7:2.47),notch=r*(single?2.57:2.35),half=r*(single?.77:.70);extend(i,dx,dy,r*2.05);arrows+=`<path d="M${x+ux*near} ${y+uy*near}L${x+ux*far-uy*half} ${y+uy*far+ux*half}L${x+ux*notch} ${y+uy*notch}L${x+ux*far+uy*half} ${y+uy*far-ux*half}Z" fill="#231f20"/>`;}
let out='';nodes.forEach((n,i)=>{if(n.piercing){const [x,y]=xy[i],o=r*8.4615/6.254,inn=r*6.325/6.254,c=r*.713/6.254;out+=`<path fill="#72bbea" fill-rule="evenodd" d="M${x-c} ${y-o}L${x+c} ${y-o}L${x+o} ${y-c}L${x+o} ${y+c}L${x+c} ${y+o}L${x-c} ${y+o}L${x-o} ${y+c}L${x-o} ${y-c}ZM${x} ${y-inn}L${x+inn} ${y}L${x} ${y+inn}L${x-inn} ${y}Z"/>`;}});
nodes.map((n,i)=>i).reverse().forEach(i=>{const [x,y]=xy[i],dpath=contour.map((p,k)=>{const q=tails[i][k]||p.map(v=>v*r);return (k?'L':'M')+(x+q[0])+' '+(y+q[1]);}).join('')+'Z';out+=`<path d="${dpath}" fill="${tiers[nodes[i].tier]}" stroke="#83847f" stroke-width=".6" stroke-linejoin="round" data-tier="${nodes[i].tier}" data-piercing="${!!nodes[i].piercing}"/>`;});
if(d.entry==='cross'){const [x,y]=xy[0];out+=`<image href="${tokenIcon('grid_enemy')}" x="${x-5.2}" y="${y-5.2}" width="10.4" height="10.4"/>`;}
const xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]),left=Math.min(...xs)-25,top=Math.min(...ys)-25,w=Math.max(...xs)-left+25,h=Math.max(...ys)-top+25;
return `<svg class="s92-track" style="width:${w*1.18}px;max-width:100%" viewBox="${left} ${top} ${w} ${h}" role="img" aria-label="${E(d.name||'伤害轨')}：${nodes.map((n,i)=>`第${i+1}点${['白色','浅灰色','深灰色'][n.tier]}${n.piercing?'穿甲伤害':''}`).join('；')}">${out+arrows}</svg>`;}
function bands(d){return `<div class="s92-thresholds">${d.attribute&&d.attribute!=='乐曲'?`<b>${E(d.attribute)}</b>`:''}${d.thresholds.map((v,i)=>`<span style="background:${tiers[i]};color:${i===2?'white':'#222c31'}">${v}${d.attribute==='乐曲'?'♪':'+'}</span>`).join('')}</div>`;}
function figure(d){return `<div class="s92-track-figure">${track(d)}${bands(d)}</div>`;}
function figures(ts,diagram){const shared=ts.length>1&&new Set(ts.map(t=>t.attribute+JSON.stringify(t.thresholds))).size===1;return `<div class="s92-figures">${ts.map(t=>shared?track(t):figure(t)).join('')}${diagram?grid(diagram):''}</div>`+(shared&&ts[0].thresholds.length?bands(ts[0]):'');}
function table(t){return `<div class="s92-results">${t.title?`<small>${E(t.title)}</small>`:''}${t.rows.map((r,i)=>`<div class="s92-result-row" style="background:${shades[Math.min(i,2)]};--s92-shade:${['#272a2a','#393c3c','#515555'][Math.min(i,2)]}">${text(r.when)} = ${text(r.effect)}</div>`).join('')}</div>`;}
function metadata(s,equipment='',first=false){const colors={'行动':'#E2B678','次级':'#8C6DA8','即时':'#9ED5C8','反应':'#E3E078','持续':'#C5DE7F'},color=Object.entries(colors).find(([k])=>s.type.startsWith(k))?.[1]||'#D7E1E2';return s.type||equipment||!first&&s.cost?`<div class="s92-meta ${equipment?'has-requirement':''}">${s.type?`<b style="background:${color}">${E(s.type)}</b>`:''}${equipment?`<span>要求：${text(equipment)}</span>`:''}${!first&&s.cost?`<strong>${text(s.cost)}</strong>`:''}</div>`:'';}
function effect(t){const f=t.face,ss=f.sections,ts=f.tracks||[],tables=f.tables||[],copy=ss.map((s,i)=>`<section>${metadata(s,i===0?f.equipment:'',i===0)}<div class="s92-copy">${text(s.body)}</div></section>`).join('');let body='';
if(f.musicGrid){body=metadata(ss[0],f.equipment,true)+`<div class="s92-music-layout">${music(f.musicGrid)}<div class="s92-music-copy">${text(ss[0].body)}</div><div class="s92-music-values">${tables.map(table).join('')}${ts.map(d=>`<div class="s92-music-track">${track(d)}<div>${d.thresholds.map((v,i)=>`<div class="s92-result-row" style="background:${shades[i]};--s92-shade:${['#272a2a','#393c3c','#515555'][i]}">${v}${note()}</div>`).join('')}</div></div>`).join('')}</div></div>`+ss.slice(1).map(s=>metadata(s)+`<div class="s92-copy">${text(s.body)}</div>`).join('');}
else if(tables.length&&ss.length===1&&!ts.length&&!f.diagram){body=metadata(ss[0],f.equipment,true)+`<div class="s92-side-results"><div class="s92-copy">${text(ss[0].body)}</div><div>${tables.map(table).join('')}</div></div>`;}
else if(f.inlineDamage){const parts=ss[0].body.split('\n');body=metadata(ss[0],f.equipment,true)+`<div class="s92-source-layout"><div><div class="s92-inline-track"><div class="s92-copy">${text(parts.shift())}</div>${track(ts[0])}</div><div class="s92-copy">${text(parts.join('\n'))}</div></div>${f.diagram?grid(f.diagram):''}</div>`;}
else if(f.diagram&&ss.length===1&&ts.length<=1&&!tables.length){body=metadata(ss[0],f.equipment,true)+`<div class="s92-source-layout"><div><div class="s92-copy">${text(ss[0].body)}</div>${ts.map(figure).join('')}</div>${grid(f.diagram)}</div>`;}
else if(f.inlineTracks){body=ss.map((s,i)=>`<section>${metadata(s,i===0?f.equipment:'',i===0)}<div class="s92-inline-track"><div class="s92-copy">${text(s.body)}</div>${ts[i]?figure(ts[i]):''}</div></section>`).join('');}
else body=copy+tables.map(table).join('')+figures(ts,f.diagram);
if(f.stances)body+=`<div class="s92-stances">${f.stances.map(s=>`<section><b>${text(s.name)}</b><p><svg viewBox="0 0 32 32" role="img" aria-label="架势标记"><rect x="2" y="2" width="28" height="28" fill="none" stroke="currentColor" stroke-dasharray="3 2"/><circle cx="16" cy="16" r="8" stroke="currentColor" fill="none"/><circle cx="16" cy="16" r="5" fill="#be303d"/></svg>${text(s.effect)}</p></section>`).join('')}</div>`;
if(f.markers){const m=f.markers,k=['mp','sp','kae','rest'].find(k=>m.refresh.includes(k))||'none';body+=`<div class="s92-markers">${Array.from({length:m.count},()=>refresh(k)).join('')}${f.markerLabels?`<small>${f.markerLabels.map(text).join('<br>')}</small>`:''}</div>`;}
return `<article class="s92-effect" data-skill-effect="${t.id}">${body}</article>`;}
function reviewed(p,id){return D.reviewed[p][id];}
function front(p,id){return reviewed(p,id)?.faces.find(f=>f.physicalSide==='front');}
function cost(p,id){const f=front(p,id);return f?.headingCost||f?.blocks?.map(b=>b.text||'').join('\n').match(/费用[:：]([^\n]+)/)?.[1]?.trim()||tile(p,id).face.sections[0].cost;}
function questions(p,id){const back=reviewed(p,id)?.faces.find(f=>f.physicalSide==='back');if(!back)return D.faq[p]?.[id]||[];let q=null,ans=[],out=[];const flush=()=>{if(q!==null)out.push({q,a:ans.join('\n')});q=null;ans=[];};for(const b of back.blocks){if(b.kind==='question'){flush();q=b.text.replace(/^问[:：]/,'').trim();}else if(b.kind==='answer')ans.push(b.text.replace(/^答[:：]/,'').trim());else if(q!==null&&b.text)ans.push(b.text);}flush();return out;}
function detail(p,id){const f=front(p,id);if(f)return `<article class="s92-description">${f.blocks.map(b=>b.kind==='source_drawing'?`<div class="s92-figures">${(tile(p,id).face.tracks||[]).map(figure).join('')}${tile(p,id).face.diagram?grid(tile(p,id).face.diagram):''}</div>`:b.text?b.kind==='heading'?`<h3>${text(b.text)}</h3>`:`<p>${text(b.text)}</p>`:'').join('')}</article>`;const r=D.rules[p][id];return `<article>${r.flavor?`<p>${text(r.flavor)}</p>`:''}<p>${text(r.prerequisiteText)}</p>${r.sections.map(s=>metadata(s)+`<p>${text(s.body)}</p>`).join('')}</article>`;}
function faq(p,id){const qs=questions(p,id);return qs.map(q=>`<details class="s92-question"><summary>${text(q.q)}</summary><div>${text(q.a)}</div></details>`).join('')+`<h3>本职业装备问答</h3>${equipment[p].map((name,i)=>`<details class="s92-question s92-equipment"><summary>${E(name)}</summary><div>${questions(p,i+1).map(q=>`<details class="s92-question"><summary>${text(q.q)}</summary><div>${text(q.a)}</div></details>`).join('')||'<p>暂无补充问答。</p>'}</div></details>`).join('')}`;}
function unlocks(p,id,c){const t=tile(p,id),st=c.skills[id]||{};return `<section class="s92-unlocks"><h3>${img('art50_learn','','')}先决条件 ${!t.requires.length?'<span>无</span>':''}</h3>${id<6?'<p>起始技能，选择本道途时自动获得。</p>':''}<div class="s92-prerequisites">${t.requires.map(n=>`<button data-skill92="open" data-id="${n}">${c.skills[n]?.learned?'✓':'○'} ${E(tile(p,n).name)}<small>${prefix[p]}-${n}</small></button>`).join('')}</div>${id>=6?`<h3>${img('art50_mastery','','')}掌握条件</h3><p>${text(t.mastery)}</p>${t.masteryDiagram?grid(t.masteryDiagram):''}${t.eureka?`<p class="s92-eureka">${symbol('insight')} 顿悟时刻：完成掌握要求后，可立即免费使用一次此技能。</p>`:''}<button class="btn primary s92-master" data-skill92="master">${st.mastered?'取消掌握':'记录掌握'}</button>`:''}</section>`;}
function show(id,tab=0){const c=H.active();if(!c)return;const p=c.path,t=tile(p,id);if(!t)return;view={p,id:+id,tab};const st=c.skills[id]||{},f=front(p,id),title=f?.title||t.name,hasCost=!!cost(p,id),cs=categories(p,id),qs=questions(p,id);const head=`<div class="s92-top"><b>${prefix[p]}-${id}</b><span>${img('art50_'+(st.mastered?'mastery':'learn'))}${st.mastered?'已掌握':st.learned?'已习得':'尚未习得'}</span></div><div class="s92-title-band" data-s92-categories="${cs.join(',')}" data-s92-cost="${hasCost}"><canvas aria-hidden="true"></canvas>${hasCost?`<strong class="s92-cost">${text(cost(p,id))}</strong>`:''}<h2>${E(title).replace(/[♪♫]/g,note())}</h2></div>`;
const labels=['技能效果','详细说明',`常见问答（${qs.length}）`],body=head+`<div class="s92-tabs" role="tablist">${labels.map((label,i)=>`<button data-skill92="tab" data-index="${i}" role="tab" aria-selected="${tab===i}">${label}</button>`).join('')}</div><div class="s92-stage" data-s92-current="${tab}">${tab===0?effect(t)+unlocks(p,id,c):tab===1?detail(p,id):faq(p,id)}</div>`;
H.modal('skillInfo',title,body);const modal=document.querySelector('.modal[data-kind="skillInfo"]');modal?.classList.add('s92-modal');paintHeaders(modal);bindSwipe(modal?.querySelector('.s92-stage'));
}
const cache=new Map();function loadImage(name){if(!cache.has(name))cache.set(name,new Promise(resolve=>{const im=new Image;im.onload=()=>resolve(im);im.src=image(name);}));return cache.get(name);}
function paintHeaders(root=document){root.querySelectorAll('[data-s92-categories]').forEach(async el=>{const canvas=el.querySelector('canvas'),cs=el.dataset.s92Categories.split(','),cost=el.dataset.s92Cost==='true',ratio=devicePixelRatio||1,w=el.clientWidth,h=el.clientHeight;canvas.width=w*ratio;canvas.height=h*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);for(const [i,cat]of cs.entries()){const im=await loadImage('art50_title_'+cat);if(!canvas.isConnected)return;ctx.save();ctx.beginPath();ctx.rect(w*i/cs.length,0,w/cs.length,h);ctx.clip();const left=Math.floor(im.width*.43),right=Math.floor(im.width*.70),fw=Math.floor(im.width*.19),sx=Math.floor(im.width*.43),cap=cost?left+im.width-right:2*(im.width-right),u=Math.min(h/im.height,(w-12)/cap),hh=im.height*u,top=(h-hh)/2,t=document.createElement('canvas');t.width=fw;t.height=im.height;t.getContext('2d').drawImage(im,sx,0,fw,im.height,0,0,fw,im.height);const pat=ctx.createPattern(t,'repeat');pat.setTransform(new DOMMatrix().translate(0,top).scale(u,u));ctx.fillStyle=pat;ctx.fillRect(0,0,w,h);
function capDraw(start,width,x,flip,paper){const piece=document.createElement('canvas'),g=piece.getContext('2d'),ww=width*u;piece.width=Math.ceil(ww*ratio);piece.height=Math.ceil(hh*ratio);g.scale(ratio,ratio);if(paper){g.fillStyle=getComputedStyle(el).getPropertyValue('--paper')||'#f8f9f3';g.fillRect(0,0,ww,hh);}g.drawImage(im,start,0,width,im.height,0,0,ww,hh);g.globalCompositeOperation='destination-in';const fade=Math.min(7,ww/4),grad=g.createLinearGradient(paper?ww-fade:0,0,paper?ww:fade,0);grad.addColorStop(0,paper?'#000':'transparent');grad.addColorStop(1,paper?'transparent':'#000');g.fillStyle=grad;g.fillRect(0,0,ww,hh);ctx.save();if(flip&&!paper){ctx.translate(x+ww,top);ctx.scale(-1,1);ctx.drawImage(piece,0,0,ww,hh);}else ctx.drawImage(piece,x,top,ww,hh);ctx.restore();}
capDraw(right,im.width-right,w-(im.width-right)*u,false,false);if(cost)capDraw(0,left,0,true,true);else capDraw(right,im.width-right,0,true,false);ctx.restore();}});}
function carried(c){const ids=c.carriedSkills?.[c.path]||[0,0,0,0,0];return `<section class="s92-carried"><h3>携带技能 <small>${ids.filter(Boolean).length} / 5</small></h3><div>${ids.map((id,i)=>`<button data-skill92="slot" data-slot="${i}"><b>${id?E(tile(c.path,id).name):'＋'}</b><small>${id?prefix[c.path]+'-'+id:i+1}</small></button>`).join('')}</div><p>点击选择或替换 · 自动保存</p></section>`;}
function chooseSlot(slot){const c=H.active(),ids=c.carriedSkills?.[c.path]||[0,0,0,0,0];H.modal('skillSlots','携带技能 · 位置 '+(slot+1),`<button class="btn" data-skill92="setSlot" data-slot="${slot}" data-id="0">清空这个位置</button><div class="s92-slot-choices">${Object.values(D.tiles[c.path]).map(t=>`<button class="btn ${ids[slot]===t.id?'primary':''}" data-skill92="setSlot" data-slot="${slot}" data-id="${t.id}" ${ids.includes(t.id)&&ids[slot]!==t.id?'disabled':''}>${E(t.name)}<small>${prefix[c.path]}-${t.id}</small></button>`).join('')}</div>`);}
function bindSwipe(el){if(!el)return;let start;el.addEventListener('pointerdown',e=>{if(e.isPrimary)start={x:e.clientX,y:e.clientY};},{passive:true});el.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.6){const next=Math.max(0,Math.min(2,view.tab+(dx<0?1:-1)));if(next!==view.tab)show(view.id,next);}},{passive:true});el.addEventListener('pointercancel',()=>start=null,{passive:true});}
function mount(){document.querySelectorAll('.s92-tree-check').forEach(el=>{const on=el.getAttribute('aria-checked')==='true',box=el.querySelector('.s92-check-art');if(on&&!box.querySelector('.s92-tick'))box.insertAdjacentHTML('beforeend',img('art50_checked','s92-tick'));if(!on)box.querySelector('.s92-tick')?.remove();});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-skill92]');if(!b||!H)return;e.preventDefault();const a=b.dataset.skill92;if(a==='open')show(+b.dataset.id);else if(a==='tab')show(view.id,+b.dataset.index);else if(a==='master'){const id=view.id;if(H.mutate(()=>H.C.toggleSkill(H.active(),id,'mastered'),false))show(id);}else if(a==='slot')chooseSlot(+b.dataset.slot);else if(a==='setSlot'){const c=H.active(),id=+b.dataset.id,slot=+b.dataset.slot;if(H.mutate(()=>{c.carriedSkills||={};const ids=[...(c.carriedSkills[c.path]||[0,0,0,0,0])];if(id&&ids.some((v,i)=>v===id&&i!==slot))throw Error('这个技能已经在携带栏中');ids[slot]=id;c.carriedSkills[c.path]=ids;},true))H.close();}});
window.addEventListener('resize',()=>paintHeaders());
window.Skills92={connect(host){H=host;},node,legend,carried,open:show,mount,effect,grid,track,music,questions,detail,table,text,data:D};
})();
